# app.R ------------------------------------------------------------------------
# WINGS: WAHIS-Informed Network for Gauging Spread of highly pathogenic avian influenza after a first detection
# Uses the all-events model.
# -----------------------------------------------------------------------------

library(shiny); library(bslib); library(data.table); library(ggplot2)
library(leaflet); library(htmlwidgets)

options(hpai.data = "data")
source("rank_cells.R")

ASSET_ERR <- tryCatch({ hpai_assets(); NA_character_ }, error = function(e) conditionMessage(e))
GRID <- if (is.na(ASSET_ERR)) hpai_assets()$grid else NULL
RES  <- HPAI_RES
N_FIXED <- 20                                    # cells highlighted in simulate mode

DEMO <- tryCatch(readRDS(file.path("data", "demo_events.rds")), error = function(e) NULL)
if (is.null(DEMO)) {
  if (is.na(ASSET_ERR)) ASSET_ERR <- "missing required file: data/demo_events.rds"
  EVENTS <- data.table(epi_event_id = numeric(0), label = character(0), ev_start = as.POSIXct(character(0)))
  ECELLS <- data.table(epi_event_id = numeric(0), cell = character(0), lon = numeric(0), lat = numeric(0),
                       cell_first = as.POSIXct(character(0)), is_first = logical(0))
} else { EVENTS <- DEMO$events; ECELLS <- DEMO$cells }
ev_choices <- setNames(EVENTS$epi_event_id, EVENTS$label)
ev_years   <- if (nrow(EVENTS)) range(as.integer(format(EVENTS$ev_start, "%Y"))) else c(NA, NA)

VAL <- tryCatch(fread(file.path("data", "validation_summary.csv"))[host_grp == "all" & rule == "combined"],
                error = function(e) NULL)
val_text <- paste0("On 23 held-out past events, the 20 highest-ranked cells contained on average 38% of the cells that were actually involved in the epidemiological event, and the 50 highest-ranked 68%.")

XSVG <- paste0('<svg xmlns="http://www.w3.org/2000/svg" width="22" height="22">',
               '<line x1="3" y1="3" x2="19" y2="19" stroke="#C0392B" stroke-width="4" stroke-linecap="round"/>',
               '<line x1="19" y1="3" x2="3" y2="19" stroke="#C0392B" stroke-width="4" stroke-linecap="round"/></svg>')
x_icon <- makeIcon(iconUrl = paste0("data:image/svg+xml;utf8,", utils::URLencode(XSVG, reserved = TRUE)),
                   iconWidth = 22, iconHeight = 22)

map_key <- function(demo, nlab) paste0(
  "<div style='background:rgba(255,255,255,.93);padding:9px 11px;border-radius:6px;",
  "box-shadow:0 1px 5px rgba(0,0,0,.3);font-size:13px;line-height:1.8;margin-bottom:26px'>",
  "<div>", XSVG, " &nbsp;Selected cell</div>",
  "<div><span style='display:inline-block;width:14px;height:14px;border:2px solid #5D3FD3;",
  "border-radius:50%;vertical-align:middle'></span> &nbsp;", nlab, " top-ranked cells</div>",
  if (demo) paste0("<div><span style='display:inline-block;width:14px;height:14px;",
                   "border:2px solid #2C3E50;background:transparent;vertical-align:middle'></span>",
                   " &nbsp;Cells involved in this event</div>") else "",
  "</div>")

APP_CSS <- HTML("
  @media (min-width: 576px) {
    .bslib-sidebar-layout { --_sidebar-width: 330px !important; }
  }
  .sidebar .form-group, .sidebar .shiny-input-container { margin-bottom: 1.5rem; min-width: 0; max-width: 100%; }
  .sidebar select, .sidebar .form-select, .sidebar .form-control { max-width: 100%; }
  .sidebar hr { margin: 1.4rem 0; opacity:.25; }
  .sidebar .alert { padding: .6rem .7rem; }
  .info-sec { font-size: 14.5px; line-height: 1.5; margin-bottom: 1.5rem; overflow-wrap: anywhere; }
  .info-sec h5 { font-size: 15.5px; font-weight: 600; margin-bottom: .4rem; }
  #mainrow { display:flex; flex-wrap:nowrap; gap:14px; align-items:flex-start; }
  #mapcol  { flex:1 1 0; min-width:0; }
  .sidewrap { flex:0 0 360px; width:360px; max-width:360px; }
  #sidecol { display:block; width:360px; max-width:100%; }
  #sidecol > * { margin-bottom:14px; }
  #sidecol .vb-row { display:grid; grid-template-columns:1fr 1fr; gap:12px; align-items:start; }
  #sidecol .vb-row .bslib-value-box { height:auto !important; min-height:0 !important; max-height:none !important;
      flex:none !important; margin:0; }
  #sidecol .bslib-value-box .value-box-value { font-size:1.6rem; }
  #sidecol .bslib-value-box .value-box-title { font-size:.95rem; }
  #map { min-height:520px; }
  @media (max-width: 1150px) {
    #mainrow { flex-wrap:wrap; }
    #mapcol, .sidewrap, #sidecol { flex:1 1 100%; width:100%; max-width:100%; }
  }
  .mode-switch { margin-bottom: 1rem; }
  .mode-switch .control-label, .mode-switch .shiny-label-null { display:none; }
  .mode-switch .shiny-options-group { display:flex; flex-direction:column; gap:8px; }
  .mode-switch .shiny-options-group .form-check, .mode-switch .shiny-options-group .radio { margin:0; padding:0; }
  .mode-switch .shiny-options-group label { display:flex; align-items:center; gap:18px; width:100%;
      margin:0; padding:12px 16px; font-size:17px; font-weight:600; line-height:1.3;
      color:#2C3E50; background:#F4F6F8; border:2px solid #DDE3E8; border-radius:10px;
      cursor:pointer; transition:all .15s ease; }
  .mode-switch .shiny-options-group label:hover { border-color:#5D3FD3; background:#EFEBFB; }
  .mode-switch input[type=radio] { width:1.2em; height:1.2em; margin:0; flex:0 0 auto;
      accent-color:#5D3FD3; float:none; position:static; }
  .mode-switch .shiny-options-group label:has(input:checked) { background:#5D3FD3; border-color:#5D3FD3;
      color:#fff; box-shadow:0 2px 8px rgba(93,63,211,.35); }
  .info-box { background-color:#EFEBFB; color:#2C3E50; border:1px solid #CFC5F2;
      border-left:4px solid #5D3FD3; border-radius:8px; }")

# keeps the map sized correctly when the metrics column is shown or hidden
RESIZE_JS <- "Shiny.addCustomMessageHandler('hpai_resize', function(x) {
  setTimeout(function(){ if (window.__hpaiMap) window.__hpaiMap.invalidateSize(); }, 200);
});"
# reports any click on the map (background, cell or marker) as input$map_anyclick
CLICK_JS <- "function(el, x) {
  var map = this; window.__hpaiMap = map;
  function send(ll) { if (!ll) return;
    Shiny.setInputValue('map_anyclick', {lat: ll.lat, lng: ll.lng, n: Math.random()}, {priority: 'event'}); }
  map.on('click', function(e) { send(e.latlng); });
  function hook(l) { if (!l || !l.on) return;
    if (l.getBounds || l.getLatLng) l.on('click', function(e) {
      send(e.latlng || (e.target.getLatLng ? e.target.getLatLng() : null)); }); }
  map.eachLayer(hook);
  map.on('layeradd', function(e) { hook(e.layer); });
}"

ui <- page_sidebar(
  title = "WINGS: WAHIS-Informed Network for Gauging Spread of highly pathogenic avian influenza \u2014 Germany pilot",
  theme = bs_theme(bootswatch = "flatly"),
  fillable = FALSE,
  tags$head(tags$style(APP_CSS), tags$script(HTML(RESIZE_JS))),
  sidebar = sidebar(
    width = 330, open = "always",
    div(class = "mode-switch",
        radioButtons("mode", NULL, c("Performance on past events" = "demo", "Simulate new events" = "free"),
                     selected = "demo", width = "100%")),
    conditionalPanel("input.mode == 'demo'",
                     div(class = "alert info-box", style = "font-size:14px",
                         sprintf("Select one of %d held-out epidemiological events (%s\u2013%s) and one of its cells. ",
                                 nrow(EVENTS), ev_years[1], ev_years[2]),
                         "The map shows the risk of HPAI occurrence linked to a target cell that notified an outbreak (X). ",
                         "None of the selectable events was used to fit the model.")),
    conditionalPanel("input.mode == 'free'",
                     div(class = "alert info-box", style = "font-size:14px",
                         "Click any cell to simulate a HPAI occurrence there. All other cells are ranked by their risk of being ",
                         sprintf("involved in the same epidemiological event; the %d highest-ranked are circled.", N_FIXED))),
    conditionalPanel("input.mode == 'demo'",
                     selectInput("event", "Past event", choices = ev_choices, selected = ev_choices[[1]], width = "100%"),
                     selectInput("cell", "Selected cell", choices = NULL, width = "100%"),
                     sliderInput("k", "N top-ranked cells", min = 5, max = 100, value = 20, step = 5, width = "100%"),
                     checkboxInput("show_truth", "Outline cells involved in this event", value = FALSE)),
    hr(),
    div(class = "info-sec", tags$h5("How to read the output"),
        "Risk is the model's estimate that a cell belongs to the same epidemiological event as the ",
        "selected cell."),
    div(class = "info-sec", tags$h5("Validation"), val_text)
  ),
  div(id = "mainrow",
      div(id = "mapcol",
          card(fill = FALSE, card_header(textOutput("map_title", inline = TRUE)),
               leafletOutput("map", height = "calc(100vh - 160px)"))),
      conditionalPanel("input.mode == 'demo'", class = "sidewrap",
                       div(id = "sidecol",
                           div(class = "vb-row",
                               value_box(title = "Sensitivity", value = textOutput("sens_v"), theme = "success", fill = FALSE,
                                         p(class = "small mb-0", textOutput("sens_sub", inline = TRUE))),
                               value_box(title = "False positive rate", value = textOutput("fpr_v"), theme = "secondary", fill = FALSE,
                                         p(class = "small mb-0", textOutput("fpr_sub", inline = TRUE)))),
                           card(fill = FALSE, card_header("Sensitivity: share of the event's other cells among the N top-ranked"),
                                card_body(fill = FALSE, plotOutput("p_sens", height = 230))),
                           card(fill = FALSE, card_header("False positive rate: share of unaffected cells among the N top-ranked"),
                                card_body(fill = FALSE, plotOutput("p_fpr", height = 230)))))
  )
)

# outlines of the cells an event reached (drawn on a map or on a leafletProxy)
add_truth <- function(map, show, cells) {
  tc <- GRID[cell %in% cells]
  if (!isTRUE(show) || !nrow(tc)) return(map)
  addRectangles(map, lng1 = tc$lon - RES/2, lat1 = tc$lat - RES/2, lng2 = tc$lon + RES/2, lat2 = tc$lat + RES/2,
                fill = FALSE, color = "#2C3E50", weight = 1.6, group = "truth")
}

server <- function(input, output, session) {
  
  output$map_title <- renderText(if (input$mode == "demo") "Predicted spread" else "Predicted spread from the selected cell")
  
  observeEvent(input$event, {
    ec  <- ECELLS[epi_event_id == as.numeric(input$event)][order(cell_first)]
    lab <- sprintf("%s (%.2f, %.2f) \u2014 %s%s", ec$cell, ec$lon, ec$lat, format(ec$cell_first, "%Y-%m-%d"),
                   ifelse(ec$is_first, "  \u2190 first notified", ""))
    updateSelectInput(session, "cell", choices = setNames(ec$cell, lab), selected = ec$cell[ec$is_first][1])
  }, ignoreInit = FALSE)
  
  observeEvent(input$mode, session$sendCustomMessage("hpai_resize", list(n = runif(1))), ignoreInit = TRUE)
  
  # --- cell selection in simulate mode -----------------------------------------
  clicked <- reactiveVal(NULL)
  pick <- function(id = NULL, lat = NULL, lng = NULL) {
    if (!is.null(id)) { id <- sub("^ring_", "", id); if (id %in% GRID$cell) return(id) }
    if (!is.null(lat) && !is.null(lng)) {
      cl <- paste(floor(lng / RES), floor(lat / RES))
      if (cl %in% GRID$cell) return(cl)
      return(GRID$cell[which.min((GRID$lon - lng)^2 + (GRID$lat - lat)^2)])
    }
    NULL
  }
  observeEvent(input$map_anyclick,    if (input$mode == "free") { p <- input$map_anyclick;    clicked(pick(NULL, p$lat, p$lng)) })
  observeEvent(input$map_shape_click, if (input$mode == "free") { p <- input$map_shape_click; clicked(pick(p$id, p$lat, p$lng)) })
  observeEvent(input$map_click,       if (input$mode == "free") { p <- input$map_click;       clicked(pick(NULL, p$lat, p$lng)) })
  observeEvent(input$map_marker_click, if (input$mode == "free") { p <- input$map_marker_click
  if (!identical(p$id, "source")) clicked(pick(p$id, p$lat, p$lng)) })
  
  kk <- reactive(if (input$mode == "demo") input$k else N_FIXED)
  src_cell <- reactive({
    if (input$mode == "demo") { req(input$cell); input$cell }
    else if (is.null(clicked())) GRID$cell[which.min((GRID$lon - 10)^2 + (GRID$lat - 51.5)^2)]
    else clicked()
  })
  truth_cells <- reactive(if (input$mode == "demo") ECELLS[epi_event_id == as.numeric(input$event)]$cell else character(0))
  
  risk <- reactive({
    validate(need(is.na(ASSET_ERR), paste("Setup problem:", ASSET_ERR)))
    S <- GRID[cell == src_cell()]
    validate(need(nrow(S) == 1, "Selected cell is outside the grid."))
    rank_cells(lon = S$lon, lat = S$lat, model = "combined")
  })
  
  curves <- reactive({
    L <- risk(); pos <- setdiff(truth_cells(), src_cell())
    validate(need(length(pos) > 0, "This event affected only the selected cell."))
    hit <- cumsum(L$cell %in% pos); k <- seq_len(nrow(L))
    data.table(k = k, sens = hit / length(pos), fpr = (k - hit) / (nrow(L) - length(pos)), n_pos = length(pos))
  })
  
  output$sens_v <- renderText(sprintf("%.1f%%", 100 * curves()$sens[kk()]))
  output$fpr_v  <- renderText(sprintf("%.1f%%", 100 * curves()$fpr[kk()]))
  output$sens_sub <- renderText({ cv <- curves()
  sprintf("%d of %d event cells found", round(cv$sens[kk()] * cv$n_pos[1]), cv$n_pos[1]) })
  output$fpr_sub <- renderText({ cv <- curves(); L <- risk()
  sprintf("%d of %d unaffected cells flagged", round(cv$fpr[kk()] * (nrow(L) - cv$n_pos[1])), nrow(L) - cv$n_pos[1]) })
  
  mini <- function(d, yv, col, ylab) {
    k0 <- kk()
    ggplot(d[k <= 200], aes(k, .data[[yv]])) +
      geom_line(colour = col, linewidth = 0.9) +
      geom_vline(xintercept = k0, linetype = 2, colour = "#2C3E50", linewidth = 0.4) +
      geom_point(data = d[k == k0], colour = "#2C3E50", size = 2.4) +
      scale_y_continuous(labels = scales::percent_format(accuracy = 1), limits = c(0, NA)) +
      labs(x = "N top-ranked cells", y = ylab) + theme_minimal(base_size = 11) +
      theme(panel.grid.minor = element_blank(), axis.title = element_text(size = 10, colour = "#5D6D7E"))
  }
  output$p_sens <- renderPlot(mini(curves(), "sens", "#18A558", "Sensitivity"))
  output$p_fpr  <- renderPlot(mini(curves(), "fpr",  "#CA6F1E", "False positive rate"))
  
  # --- map ------------------------------------------------------------------------
  output$map <- renderLeaflet({
    L  <- risk()
    mp <- merge(GRID[, .(cell, lon, lat)], L[, .(cell, risk, rank, dist_km, travel_h)], by = "cell", all.x = TRUE)
    pal <- colorNumeric("YlOrRd", domain = c(0, max(L$risk)), na.color = "#BFC9CA")
    S   <- GRID[cell == src_cell()]
    lab <- sprintf("<b>%s</b><br/>Risk %s<br/>Rank %s<br/>%s km, %s h by road", mp$cell,
                   ifelse(is.na(mp$risk), "\u2014", sprintf("%.3f", mp$risk)), ifelse(is.na(mp$rank), "\u2014", mp$rank),
                   ifelse(is.na(mp$dist_km), "\u2014", mp$dist_km), ifelse(is.na(mp$travel_h), "\u2014", mp$travel_h))
    zm <- isolate(input$map_zoom); ctr <- isolate(input$map_center)
    m <- leaflet(options = leafletOptions(minZoom = 4)) |>
      addProviderTiles("Esri.WorldStreetMap") |>
      addRectangles(lng1 = mp$lon - RES/2, lat1 = mp$lat - RES/2, lng2 = mp$lon + RES/2, lat2 = mp$lat + RES/2,
                    fillColor = pal(mp$risk), fillOpacity = 0.62, weight = 0, layerId = mp$cell,
                    label = lapply(lab, HTML), group = "risk") |>
      addLegend(position = "bottomright", pal = pal, values = c(0, max(L$risk)), title = "HPAI risk", opacity = 0.8) |>
      addControl(HTML(map_key(input$mode == "demo", kk())), position = "bottomleft") |>
      addMarkers(lng = S$lon, lat = S$lat, icon = x_icon, layerId = "source",
                 label = HTML(paste0("<b>Selected cell ", S$cell, "</b>")))
    m <- if (!is.null(zm) && !is.null(ctr)) m |> setView(lng = ctr$lng, lat = ctr$lat, zoom = zm)
    else m |> fitBounds(min(GRID$lon), min(GRID$lat), max(GRID$lon), max(GRID$lat))
    # The whole map is rebuilt whenever the selected cell or N changes (this wipes anything added
    # through leafletProxy), so the event outlines are drawn here too, using the current switch.
    m <- add_truth(m, isolate(input$mode == "demo" && isTRUE(input$show_truth)), isolate(truth_cells()))
    m |> onRender(CLICK_JS)
  })
  
  observe({                                        # switch on/off without rebuilding the map
    show <- input$mode == "demo" && isTRUE(input$show_truth)
    tc   <- truth_cells()
    leafletProxy("map") |> clearGroup("truth") |> add_truth(show, tc)
  })
  
  observe({                                        # rings around the N top-ranked cells
    L <- risk(); top <- L[rank <= kk()]
    leafletProxy("map") |> clearGroup("topn") |>
      addCircleMarkers(lng = top$lon, lat = top$lat, radius = 6, fill = FALSE, color = "#5D3FD3", weight = 2.2,
                       group = "topn", layerId = paste0("ring_", top$cell),
                       label = lapply(sprintf("<b>Rank %d</b><br/>risk %.3f", top$rank, top$risk), HTML))
  })
}

shinyApp(ui, server)
